		["Less visible muzzle flash"] = ("Flash de bouche moins visible", "Weniger sichtbares Mündungsfeuer", "Fogonazo menos visible", "Clarão do disparo menos visível"),
		["Earlier damage falloff at distance; shorter gas system fires faster"] = (
			"Les dégâts diminuent plus tôt avec la distance ; un circuit de gaz plus court tire plus vite",
			"Früherer Schadensabfall auf Distanz; ein kürzeres Gassystem feuert schneller",
			"El daño cae antes con la distancia; un sistema de gas más corto dispara más rápido",
			"O dano cai mais cedo com a distância; um sistema de gás mais curto dispara mais rápido" ),
		["Earlier damage falloff at distance"] = ("Les dégâts diminuent plus tôt avec la distance", "Früherer Schadensabfall auf Distanz", "El daño cae antes con la distancia", "O dano cai mais cedo com a distância"),
		["Later damage falloff at distance; longer gas system fires slower"] = (
			"Les dégâts diminuent plus tard avec la distance ; un circuit de gaz plus long tire plus lentement",
			"Späterer Schadensabfall auf Distanz; ein längeres Gassystem feuert langsamer",
			"El daño cae más tarde con la distancia; un sistema de gas más largo dispara más despacio",
			"O dano cai mais tarde com a distância; um sistema de gás mais longo dispara mais devagar" ),
		["Later damage falloff at distance"] = ("Les dégâts diminuent plus tard avec la distance", "Späterer Schadensabfall auf Distanz", "El daño cae más tarde con la distancia", "O dano cai mais tarde com a distância"),
		["Less shoulder support; more recoil"] = ("Moins d'appui à l'épaule ; plus de recul", "Weniger Schulterauflage; mehr Rückstoß", "Menos apoyo en el hombro; más retroceso", "Menos apoio no ombro; mais recuo"),
		["More shoulder support; less recoil"] = ("Plus d'appui à l'épaule ; moins de recul", "Mehr Schulterauflage; weniger Rückstoß", "Más apoyo en el hombro; menos retroceso", "Mais apoio no ombro; menos recuo"),
		["Lighter support; slightly more recoil"] = ("Appui plus léger ; un peu plus de recul", "Leichtere Auflage; etwas mehr Rückstoß", "Apoyo más ligero; algo más de retroceso", "Apoio mais leve; um pouco mais de recuo"),
		["Reduces recoil while prone"] = ("Réduit le recul à plat ventre", "Verringert den Rückstoß im Liegen", "Reduce el retroceso cuerpo a tierra", "Reduz o recuo quando deitado"),
		["Improves horizontal recoil control"] = ("Améliore le contrôle du recul horizontal", "Verbessert die horizontale Rückstoßkontrolle", "Mejora el control del retroceso horizontal", "Melhora o controle do recuo horizontal"),
		["Improves vertical recoil control"] = ("Améliore le contrôle du recul vertical", "Verbessert die vertikale Rückstoßkontrolle", "Mejora el control del retroceso vertical", "Melhora o controle do recuo vertical"),
		["Slightly improves recoil control"] = ("Améliore légèrement le contrôle du recul", "Verbessert die Rückstoßkontrolle leicht", "Mejora ligeramente el control del retroceso", "Melhora levemente o controle do recuo"),

		// Part descriptions (GunsmithPart.Description, Assets/gunsmith). A description written again with new figures shows in
		// English until it's added here.
		["20 rounds · 10% faster reload"] = ("20 cartouches · Rechargement 10 % plus rapide", "20 Schuss · 10 % schnelleres Nachladen", "20 balas · Recarga un 10 % más rápida", "20 cartuchos · Recarga 10% mais rápida"),
		["40 rounds · 15% slower reload"] = ("40 cartouches · Rechargement 15 % plus lent", "40 Schuss · 15 % langsameres Nachladen", "40 balas · Recarga un 15 % más lenta", "40 cartuchos · Recarga 15% mais lenta"),
		["25-round drum. Much heavier and slower to change. Reloads in 3.17s (4.2s when empty)."] = (
			"Tambour de 25 cartouches. Bien plus lourd et plus lent à changer. Rechargement en 3,17 s (4,2 s à vide).",
			"25-Schuss-Trommel. Deutlich schwerer und langsamer zu wechseln. Nachladen in 3,17 s (4,2 s wenn leer).",
			"Tambor de 25 cartuchos. Mucho más pesado y lento de cambiar. Recarga en 3,17 s (4,2 s en vacío).",
			"Tambor de 25 cartuchos. Muito mais pesado e lento para trocar. Recarga em 3,17 s (4,2 s vazio)." ),
		["30-round magazine configured for 10mm ammunition."] = ("Chargeur de 30 cartouches configuré pour les munitions de 10 mm.", "30-Schuss-Magazin für 10-mm-Munition.", "Cargador de 30 balas configurado para munición de 10 mm.", "Carregador de 30 cartuchos configurado para munição 10 mm."),
		["40-round magazine. Sticks out further below the grip. Reloads in 2.53s (3.23s when empty)."] = (
			"Chargeur de 40 cartouches. Dépasse davantage sous la poignée. Rechargement en 2,53 s (3,23 s à vide).",
			"40-Schuss-Magazin. Ragt weiter unter dem Griff hervor. Nachladen in 2,53 s (3,23 s wenn leer).",
			"Cargador de 40 balas. Sobresale más por debajo de la empuñadura. Recarga en 2,53 s (3,23 s en vacío).",
			"Carregador de 40 cartuchos. Fica mais saliente abaixo da empunhadura. Recarga em 2,53 s (3,23 s vazio)." ),
		["40mm underbarrel launcher"] = ("Lance-grenades de 40 mm sous le canon", "40-mm-Unterlauf-Granatwerfer", "Lanzagranadas de 40 mm bajo el cañón", "Lança-granadas de 40 mm sob o cano"),
		["50-round magazine. Long and heavy, well below the grip. Reloads in 2.53s (3.23s when empty)."] = (
			"Chargeur de 50 cartouches. Long et lourd, il descend bien sous la poignée. Rechargement en 2,53 s (3,23 s à vide).",
			"50-Schuss-Magazin. Lang und schwer, ragt weit unter den Griff. Nachladen in 2,53 s (3,23 s wenn leer).",
